{
  "items": [
    {
      "asset": "PLOZASIRAN (ARO-APOC3)",
      "mechanism": "suppress the production of apolipoprotein C-III (APOC3)",
      "modality": "small interfering RNA (siRNA)",
      "quotes": [
        "REDEMPLO is a small interfering RNA (“siRNA”) therapeutic designed to suppress the production of apolipoprotein C-III (APOC3), a protein produced in the liver that raises triglyceride levels by slowing their breakdown and clearance."
      ]
    },
    {
      "asset": "ARO-PNPLA3",
      "mechanism": "reduce liver expression of patatin-like phospholipase domain containing 3 (PNPLA3)",
      "modality": "RNA interference (RNAi) therapeutic",
      "quotes": [
        "Announced an exclusive worldwide license agreement with Madrigal Pharmaceuticals for ARO-PNPLA3, Arrowhead’s clinical stage RNA interference (RNAi) therapeutic designed to reduce liver expression of patatin-like phospholipase domain containing 3 (PNPLA3) as a potential treatment for patients with metabolic dysfunction-associated steatohepatitis (MASH)"
      ]
    },
    {
      "asset": "ARO-INHBE",
      "mechanism": "",
      "modality": "RNA interference (RNAi) therapeutic",
      "quotes": [
        "Presented interim results from a Phase 1/2a clinical trial of ARO-INHBE, the Company’s investigational RNA interference (RNAi) therapeutic being developed as a potential treatment for obesity and metabolic dysfunction-associated steatohepatitis (MASH)."
      ]
    },
    {
      "asset": "ARO-DIMER-PA",
      "mechanism": "silence expression of both proprotein convertase subtilisin kexin 9 (PCSK9) and apolipoprotein C3 (APOC3) genes",
      "modality": "RNAi therapeutic",
      "quotes": [
        "Initiated and dosed the first subjects in a Phase 1/2a clinical trial of ARO-DIMER-PA, the Company’s investigational RNAi therapeutic being developed as a potential treatment for atherosclerotic cardiovascular disease (ASCVD) due to mixed hyperlipidemia.",
        "ARO-DIMER-PA is designed to silence expression of both proprotein convertase subtilisin kexin 9 (PCSK9) and apolipoprotein C3 (APOC3) genes."
      ]
    },
    {
      "asset": "ARO-ALK7",
      "mechanism": "",
      "modality": "RNAi-therapeutic",
      "quotes": [
        "ARO-ALK7, the first RNAi-therapeutic to show adipocyte gene target silencing in a clinical trial, achieved dose dependent reductions in adipose ALK7 messenger (mRNA) with a mean reduction of -88% at the 200 mg dose at week 8 with a maximum reduction of -94%."
      ]
    },
    {
      "asset": "ARO-MAPT",
      "mechanism": "",
      "modality": "RNAi therapeutic",
      "quotes": [
        "Initiated and dosed the first subjects in a Phase 1/2a clinical trial of ARO-MAPT, the Company’s investigational RNAi therapeutic being developed as a potential treatment for tauopathies including Alzheimer’s disease, a progressive neurodegenerative disease characterized by cognitive and functional decline."
      ]
    },
    {
      "asset": "ARO-DM1",
      "mechanism": "",
      "modality": "RNAi therapeutic",
      "quotes": [
        "the Company earned a $200.0 million milestone payment from Sarepta Therapeutics, Inc., which was triggered on November 20, 2025, when the Company reached the second of two prespecified enrollment targets and subsequent authorization to dose escalate in a Phase 1/2 clinical study of ARO-DM1, an investigational RNAi therapeutic for the treatment of type 1 myotonic dystrophy (DM1)."
      ]
    }
  ]
}
